1	/* ============================ Lái xe: điều phối chế độ (lái một mình, máy tính) ============================
2	   Nối mạng đường (net / roadData / solids / sceneSolids), chuyển động + va chạm (motion / collide), hình xe (car / cars),
3	   camera sau xe (camera) với vòng animate, phím, chuột, cảm ứng (touch), HUD (hud: đồng hồ, bản đồ nhỏ, gợi ý), tiếng mô tơ / còi (sound). Mẫu: explore/stroll/index.ts.
4	   `?explore=drive` vào thẳng, lái một mình; thẻ "Ô tô" ở màn chọn: có máy chủ thì qua sảnh 5 chỗ lái (phiên kind 'drive'), không thì lái một mình.
5	   Esc và nút Thoát dùng explore.exit() (tải lại trang, D-020); trước đó drive.stop() trả lại các thứ đã đổi.
6	   - Mạng đường dựng MỘT lần ở lần đầu vào chế độ và giữ lại: ô tĩnh + vật cản tĩnh + nhà / chân đế thu từ cảnh (drCollectRuntime chỉ push,
7	     gọi hai lần sẽ nhân đôi vật cản). Chỉ đọc cảnh, sau mọi rand().
8	   - Barie Cầu sông Hàn: cổng DR_GATE_SWING của ô nhịp quay đóng khi cầu rời CLOSED (mỗi khung); không tự quay, không tăng tốc quay (như đi dạo).
9	     Xe đang chạm nhịp quay lúc đó được sơ tán ra ngoài barie gần nhất (motion.ts drEvacStep), gói trong thời gian còn lại trước khi nhịp xoay
10	     (drSwingBudget: coi như nhịp không phải chờ xe tự động rời nhịp, tức thời gian ngắn nhất).
11	   - Xe tự động: mỗi khung lấy hộp các xe đang hiện trong bán kính CONFIG.drive.ai.radius (common/trafficQuery.ts trNearby, mảng tái dùng);
12	     người chơi lao vào thì bị chặn, xe tự động chạy tới thì đi xuyên (collide.ts drMove).
13	   - Ban đêm Cầu Rồng tự phun như khi đi dạo (exNightStep, swing = false).
14	   - Hầm: driveView.far = CONFIG.drive.tunnelFar khi đang lái để mặt đường hầm hiện ở nút giao với hai đường dọc mới; thoát trả 1.
15	   - Xe của mình nằm trong drCars ở slot của mình (màu theo slot, multiParams.colors) hoặc slot 0 khi lái một mình; xe và bánh chỉ vào cảnh khi có xe (multi/index.ts gắn drCars.group
16	     theo exDrivers.onCars), góc nhìn cũ không thêm lệnh vẽ.
17	   - Nhiều người (exMulti, phiên kind 'drive'): xuất phát theo slot, gửi vị trí + vận tốc + góc lái sendHz lần/s (cả lúc đang sơ tán khỏi nhịp quay); xe người khác (exDrivers) không tham gia va chạm
18	     (chỉ vẽ, nhãn tên, chấm trên bản đồ nhỏ). Hết chỗ lái thì chế độ xem (startWatching): camera sau xe được xem, không điều khiển, đồng hồ + bản đồ theo xe đó; rời máy thì nhường chỗ sang xem.
19	   - Phím theo e.code (keys.ts), chỉ ghi khi đang lái, bỏ qua ô nhập và tổ hợp Ctrl / Meta / Alt; blur, ẩn tab, focus vào ô nhập thì nhả hết.
20	   - Cảm ứng (touch.ts, #drHud): đọc SAU phím và gộp (giá trị có độ lớn lớn hơn), không xóa phím trên máy lai; reset() cùng chỗ nhả phím. Phím H: còi.
21	   Mỗi khung không cấp phát (D-018). */
22	import type * as THREE from 'three';
23	import { scene, camera, controls, canvas, renderer } from '../../core/renderer';
24	import { composer, onResize } from '../../core/postprocessing';
25	import { cam } from '../../views/state';
26	import { CONFIG } from '../../config';
27	import { driveView } from '../../environment/driveRoads';
28	import { drMakeNet, drSetGate, type DrNet } from './net';
29	import { drBuildPads, DR_GATE_SWING } from './roadData';
30	import { drBuildSolids } from './solids';
31	import { drCollectRuntime, drSceneStats } from './sceneSolids';
32	import { drCreate, drStep, drEvacStep, type DrState, type DrInput } from './motion';
33	import { trNearby } from '../../common/trafficQuery';
34	import type { DrBox } from './collide';
35	import { drCarLoad, drCarSetWarm } from './car';
36	import { drCars } from './cars';
37	import { drCamPlace, drCamDrag, type DrCam } from './camera';
38	import { drInputFromKeys, drBindDrop, DR_KEYS } from './keys';
39	import { drHudShow, drHudHide, drHudUpdate } from './hud';
40	import { drTouchBind } from './touch';
41	import { drSound } from './sound';
42	import { exNightStep } from '../nightShows';
43	import { exMulti } from '../multi';
44	import { exDrivers } from '../multi/remoteDrive';
45	import { exWatchShow, exWatchHide, exWatchRender, exFlyNotice } from '../multi/watch';
46	import type { SwingController } from '../../bridges/song-han/SwingController';
47	
48	const DR_SOLO_SLOT = -1;     // drCreate / drSpawnPose: lái một mình xuất phát ở giữa các chỗ của slot
49	const DR_SELF = 0;           // slot xe của mình trong drCars khi lái một mình (màu slot 0); có chỗ thật thì dùng slot được cấp
50	
51	/* Làm nóng shader của xe (D-018), như stroll/index.ts stRigSetWarm: hai biến thể (vẽ thẳng ra canvas ban ngày, vào render target của composer ban đêm),
52	   đèn / sương / bóng lấy từ cảnh chính, camera chính (đèn lọc theo lớp của nó). Nhóm làm nóng do car.ts dựng, không thêm vào scene */
53	drCarSetWarm(async (o: THREE.Object3D) => {
54	  const rt = renderer.getRenderTarget();
55	  renderer.setRenderTarget(null);
56	  const a = renderer.compileAsync(o, camera, scene);
57	  renderer.setRenderTarget(rt);
58	  await a;
59	  renderer.setRenderTarget(composer.readBuffer);
60	  const b = renderer.compileAsync(o, camera, scene);
61	  renderer.setRenderTarget(rt);
62	  await b;
63	});
64	
65	let net: DrNet | null = null;
66	let state: DrState | null = null;
67	let ctrl: SwingController | null = null;
68	const drKeys = new Set<string>();  // e.code đang giữ
69	const camS: DrCam = { yaw: 0, pitch: 0, idle: 0 };
70	const _inp: DrInput = { gas: 0, brake: 0, steer: 0, hand: false };   // đầu vào tái dùng mỗi khung
71	let selfSlot = DR_SELF;            // slot xe của mình trong drCars
72	let watching = false;              // đang xem xe người khác (hết chỗ lái hoặc vừa nhường chỗ): không có xe của mình, không đọc phím
73	let chased = false;                // camera đã bám xe được xem lần nào chưa (lần đầu đặt thẳng, không trượt từ xa)
74	let exit: () => void = () => {};   // thoát chung (explore.exit), dùng khi mất kết nối lúc đang xem
75	const _ws = { x: 0, z: 0, yaw: 0, v: 0 };   // xe đang xem đưa cho HUD (đồng hồ, bản đồ nhỏ), tái dùng mỗi khung
76	let touch: ReturnType<typeof drTouchBind> | null = null;   // điều khiển cảm ứng (setupDrive dựng)
77	const boxes: DrBox[] = [];         // hộp xe tự động gần xe, tái dùng mỗi khung (trNearby chỉ thêm phần tử khi phải nới)
78	let saved: { fov: number; explore: boolean } | null = null;   // thứ start() đổi, stop() trả lại: fov camera, lớp body 'explore' đã có từ trước chưa
79	
80	const active = () => cam.mode === 'car' && state !== null;
81	const inMode = () => active() || watching;   // Esc và giao diện lái áp cho cả chế độ xem
82	const isField = (t: EventTarget | null) => !!t && /^(SELECT|INPUT|TEXTAREA)$/.test((t as HTMLElement).tagName || '');
83	
84	/* Mạng đường dựng lần đầu vào chế độ, giữ lại cho các lần sau; cổng nhịp quay theo cầu hiện tại */
85	function drEnsureNet(): DrNet {
86	  if (!net) {
87	    const n = drMakeNet(drBuildPads(), drBuildSolids());
88	    drCollectRuntime(n, (scene.getObjectByName('tp-houses') as THREE.InstancedMesh) || null);   // một lần cho mỗi net (chỉ push)
89	    net = n;                                                         // gán sau khi thu xong: thu lỗi thì lần vào sau thu lại từ đầu
90	  }
91	  if (ctrl) drSetGate(net, DR_GATE_SWING, ctrl.state !== 'CLOSED');
92	  return net;
93	}
94	
95	/* Giây (thời gian thật) còn lại tới lúc nhịp quay bắt đầu xoay (ROTATING_OPEN), giả sử nhịp không phải chờ xe tự động rời nhịp
96	   (spanClear đúng ngay: thời gian ngắn nhất); 0 khi nhịp đã / đang xoay hoặc cầu đóng: drEvacStep coi 0 là hết hạn (trượt trong evac.minTime), khác bỏ trống (không hạn) */
97	function drSwingBudget(c: SwingController): number {
98	  const T = c.cfg.timing, sp = c.speed > 0 ? c.speed : 1;
99	  if (c.state === 'STOP_TRAFFIC') return Math.max(0, T.amber + T.barrier - c.t + T.unlock) / sp;
100	  if (c.state === 'UNLOCK') return Math.max(0, T.unlock - c.t) / sp;
101	  return 0;
102	}
103	
104	/* Một bước: cổng nhịp quay, sơ tán / chuyển động, hình xe, camera, hiệu ứng đêm */
105	function advance(dt: number, inp: DrInput): void {
106	  if (ctrl) drSetGate(net!, DR_GATE_SWING, ctrl.state !== 'CLOSED');
107	  const s = state!;
108	  if (!drEvacStep(s, net!, dt, ctrl ? drSwingBudget(ctrl) : undefined)) drStep(s, inp, net!, boxes, trNearby(s.x, s.z, CONFIG.drive.ai.radius, boxes), dt);
109	  drCars.place(selfSlot, state!);
110	  drCamPlace(camera, state!, camS, net!, dt);
111	  controls.target.set(state!.x, state!.y, state!.z);   // tâm vùng bóng đổ (main.ts shadowCenter) theo xe
112	  const now = performance.now();
113	  exMulti.update(dt, now, null);     // xe người khác, người bay / đi dạo, nhãn tên; không làm gì khi lái một mình
114	  exMulti.updateDrive(now, state);   // gửi vị trí + vận tốc + góc lái khi đang giữ chỗ (kể cả lúc sơ tán)
115	  drHudUpdate(state!, exDrivers.dots()); drSound.update(state!.v);
116	  exNightStep(dt, false);
117	}
118	
119	/* Mỗi khung khi xem: xe người khác, nhãn, danh sách; camera sau xe được xem (hướng bám hướng xe đó), đồng hồ và bản đồ nhỏ theo xe đó. Không có ai thì giữ nguyên */
120	function watchStep(dt: number): void {
121	  if (ctrl) drSetGate(net!, DR_GATE_SWING, ctrl.state !== 'CLOSED');
122	  exMulti.update(dt, performance.now(), null);
123	  const w = exMulti.watchDriver();
124	  if (w) {
125	    drCamPlace(camera, w, camS, net!, dt, !chased); chased = true;
126	    controls.target.set(w.x, w.y, w.z);
127	    _ws.x = w.x; _ws.z = w.z; _ws.yaw = w.yaw; _ws.v = w.v;
128	    drHudUpdate(_ws, exDrivers.dots(w));
129	  }
130	  exNightStep(dt, false);
131	}
132	
133	/* Đổi phiên khi đang xem hoặc đang lái: vào lái, mất kết nối, bị thu hồi chỗ (như stOnMultiChange của đi dạo) */
134	function drOnMultiChange(): void {
135	  const s = exMulti.session; if (!s) return;
136	  if (watching) {
137	    if (s.phase === 'flying') { drive.start(); return; }   // chấp nhận lời mời: xuất phát như vào lái thường
138	    if (s.phase === 'solo') { try { sessionStorage.setItem('exMpNotice', 'lostDrive'); } catch { /* bộ nhớ bị chặn */ } exit(); return; }   // màn chọn đọc cờ này và hiện drLostChooser
139	    exWatchRender();
140	  } else if (active()) {
141	    if (s.phase === 'watching') { drive.startWatching(true); return; }   // chỗ bị thu hồi (rời máy): sang xem, camera giữ nguyên
142	    if (s.phase === 'solo' && s.notice === 'lost') exFlyNotice(s, 'drLost');   // vẫn lái, người khác đã biến mất
143	  }
144	}
145	
146	/* Xe đứng yên ở (x, z) hướng yaw, trạng thái mới từ drCreate (xóa trạng thái cọ tường); y bỏ trống thì lấy mặt đường cao nhất tại đó.
147	   Dùng cho test (__app.drive) và đặt lại vị trí */
148	function drPlaceAt(x: number, z: number, yaw: number, y?: number): void {
149	  if (!net) return;
150	  const s = drCreate(net, DR_SOLO_SLOT);
151	  let gy = -Infinity;
152	  for (const p of net.pads) {
153	    if (x < p.x0 || x > p.x1 || z < p.z0 || z > p.z1 || (p.gate !== undefined && net.closed.has(p.gate))) continue;
154	    gy = Math.max(gy, p.y(x, z));
155	  }
156	  s.x = x; s.z = z; s.yaw = yaw; s.y = y ?? (Number.isFinite(gy) ? gy : CONFIG.roadY);
157	  state = s;
158	  camS.yaw = 0; camS.pitch = 0; camS.idle = 0;
159	  drCars.place(selfSlot, s);
160	  drCamPlace(camera, s, camS, net, 0, true);
161	  controls.target.set(s.x, s.y, s.z);
162	}
163	
164	export const drive = {
165	  active,
166	  inMode,
167	  get watching(): boolean { return watching; },
168	  get state(): DrState | null { return state; },
169	  get net(): DrNet | null { return net; },
170	  get cam(): DrCam { return camS; },
171	  /* Vào lái: một mình (không phiên / ngoại tuyến) hoặc với slot lái vừa được cấp (xuất phát theo slot, màu xe theo slot) */
172	  start(): void {
173	    if (watching) { watching = false; document.body.classList.remove('ex-watching'); exWatchHide(); }
174	    const n = drEnsureNet(), s = exMulti.session;
175	    const slot = s && s.kind === 'drive' && s.mySlot >= 0 ? s.mySlot : DR_SOLO_SLOT;
176	    if (s) exMulti.onChange = drOnMultiChange;
177	    selfSlot = slot >= 0 ? slot : DR_SELF;
178	    state = drCreate(n, slot);
179	    camS.yaw = 0; camS.pitch = 0; camS.idle = 0;
180	    exDrivers.setSelf(selfSlot);   // dựng xe của mình; drCars.group vào cảnh nhờ exDrivers.onCars (multi/index.ts)
181	    drCars.place(selfSlot, state);
182	    driveView.far = CONFIG.drive.tunnelFar;
183	    drKeys.clear(); touch?.reset();
184	    drHudShow(n); drSound.start();
185	    if (!saved) saved = { fov: camera.fov, explore: document.body.classList.contains('explore') };
186	    cam.flight.then = null; cam.mode = 'car'; controls.enabled = false;
187	    camera.fov = CONFIG.drive.cam.fov; onResize();   // onResize cập nhật ma trận chiếu và hệ số cỡ điểm theo fov mới
188	    drCamPlace(camera, state, camS, n, 0, true);
189	    controls.target.set(state.x, state.y, state.z);
190	    document.body.classList.add('explore', 'drive');
191	  },
192	  /* Chế độ xem bám xe người khác (hết chỗ lái, hoặc vừa nhường chỗ do rời máy): cam.mode = 'car' nhưng không có xe / trạng thái của mình, không đọc phím, không tiếng mô tơ;
193	     carry = true khi vừa nhường chỗ (camera đang ở sau xe cũ, trượt dần sang xe được xem). Không có phiên thì không làm gì */
194	  startWatching(carry = false): void {
195	    const s = exMulti.session; if (!s) return;
