242	/* onExit: thoát chung (explore.exit), dùng khi mất kết nối lúc đang xem */
243	export function setupDrive(c: SwingController, onExit: () => void): void {
244	  ctrl = c; exit = onExit;
245	  window.addEventListener('keydown', (e) => {
246	    if (!active() || e.key === 'Escape') return;   // Esc do explore/index.ts xử lý (thoát chung)
247	    if (e.ctrlKey || e.metaKey || e.altKey) return;   // phím tắt trình duyệt không điều khiển xe, tránh kẹt phím
248	    if (isField(e.target)) return;                    // gõ trong ô nhập / chọn không điều khiển xe
249	    if (!DR_KEYS.has(e.code)) return;
250	    exMulti.activity();   // phím điều khiển (kể cả tự lặp) tính là còn đó
251	    if (e.code.startsWith('Arrow') || e.code === 'Space') e.preventDefault();   // không cuộn trang, Space không bấm nút đang focus
252	    drKeys.add(e.code);
253	  });
254	  window.addEventListener('keyup', (e) => {
255	    drKeys.delete(e.code);
256	    if (e.code === 'Space' && active() && !isField(e.target)) e.preventDefault();
257	  });
258	  const drop = drBindDrop(window, document, drKeys);
259	  window.addEventListener('focusin', (e) => { if (active() && isField(e.target)) { drop(); touch?.reset(); drSound.horn(false); } });
260	  /* Tab ẩn hoặc mất tiêu điểm: vòng khung có thể dừng nên tắt còi ngay (phím đã nhả ở drBindDrop, cảm ứng tự reset trong touch.ts) */
261	  window.addEventListener('blur', () => drSound.horn(false));
262	  document.addEventListener('visibilitychange', () => { if (document.hidden) drSound.horn(false); });
263	  drSound.bind(document.getElementById('drSoundBtn'));   // nút 🔊 / 🔇: cách duy nhất bật tiếng xe khi chưa bật âm thanh chung (nút nhạc ẩn trong chế độ khám phá)
264	  const hud = document.getElementById('drHud');
265	  if (hud) touch = drTouchBind(hud, {
266	    look: (dx, dy) => { if (active()) drCamDrag(camS, dx, dy); },
267	    activity: () => exMulti.activity()
268	  });
269	  /* Kéo chuột trái trên canvas: xoay camera quanh xe (ngón tay vuốt #drLook trong touch.ts) */
270	  let dragId = -1, lx = 0, ly = 0;
271	  canvas.addEventListener('pointerdown', (e) => {
272	    if (!active() || e.pointerType === 'touch' || e.button !== 0) return;
273	    dragId = e.pointerId; lx = e.clientX; ly = e.clientY;
274	    canvas.setPointerCapture(e.pointerId);
275	  });
276	  canvas.addEventListener('pointermove', (e) => {
277	    if (e.pointerId !== dragId) return;
278	    drCamDrag(camS, e.clientX - lx, e.clientY - ly);
279	    lx = e.clientX; ly = e.clientY;
280	  });
281	  const end = (e: PointerEvent) => { if (e.pointerId === dragId) dragId = -1; };
282	  canvas.addEventListener('pointerup', end);
283	  canvas.addEventListener('pointercancel', end);
284	  canvas.addEventListener('lostpointercapture', end);
285	}
