1	/* ============================ Lái xe: chuyển động theo số liệu VF 3 ============================
2	   Mô hình "xe đạp" động học trên mặt bằng (spec §5.2): vị trí, hướng, tốc độ dọc có dấu, góc lái; không mô phỏng lốp, treo, trượt.
3	   - Tăng tốc: a = a0 không đổi tới 50 km/h (a0 = 50 km/h / t50, qua đúng mốc thứ nhất), sau đó a = a0 · v50 / v · (1 − u^k)
4	     với u = (v − v50) / (vMax − v50): giảm theo công suất không đổi và về 0 tại vMax. Số mũ k giải một lần (chia đôi) sao cho tới
5	     99 % vMax (27,5 m/s ≈ 100 km/h, vì đường cong chỉ tiệm cận vMax) đúng t100.
6	   - Lái: góc lái lớn nhất asin(wheelbase / turnRadius) (bán kính quay vòng tính ở tâm trục trước); tốc độ cao thì giới hạn thêm
7	     sao cho gia tốc ngang v² · tan(góc) / wheelbase ≤ latMax. Góc lái tiến về đích theo steerRate, tự trả về 0 theo steerReturn
8	     (cả hai là phần góc lái lớn nhất mỗi giây).
9	   - Phanh / lùi: phanh khi đang tiến; |v| < sim.revV mà giữ phanh, không ga thì lùi dần tới reverseMax; đang lùi mà đạp ga thì phanh
10	     về 0 rồi mới tiến. Nhả hết thì chậm dần theo coast, không tự lùi. Phanh tay hãm handBrake, không trượt. Dốc không đổi gia tốc.
11	   - drStep chia dt thành bước ≤ sim.dt (tối đa sim.steps bước, phần dư bỏ); mỗi bước dời thân xe bằng drMove (collide.ts);
12	     bị chặn thì mất phần tốc độ hướng vào vật cản một lần (đâm thẳng thì đứng hẳn, cọ chéo còn phần chiếu dọc vật cản),
13	     đang cọ thì hãm thêm perf.scrape (m/s²); kết quả không phụ thuộc tần số khung.
14	   - Sơ tán (drEvacStep): cổng nhịp quay Cầu sông Hàn đóng (cầu rời CLOSED) mà thân xe còn chạm ô nhịp quay thì người chơi mất điều khiển,
15	     xe trượt thẳng (nội suy đều vị trí, hướng) tới chỗ đậu ngoài barie gần nhất, đi xuyên xe tự động đang xếp hàng; xong thì trả điều khiển.
16	     Không đi qua drMove: thân xe thiếu mặt đường ở cả 9 điểm mẫu thì đường thoát của drMove (số điểm thiếu không tăng) để xe lái tự do
17	     trên không. Thời gian trượt theo evac.speed, nhưng gói trong phần thời gian còn lại trước khi nhịp xoay (budget, do index.ts tính).
18	   Không cấp phát mỗi khung (D-018). Không import three. */
19	import { CONFIG } from '../../config';
20	import { drGround, type DrNet } from './net';
21	import { drSpawnPose } from './roadData';
22	import { drMove, drFits, type DrPose, type DrBox } from './collide';
23	import { SH } from '../../bridges/song-han/profile';
24	
25	export interface DrState extends DrPose { pitch: number; v: number; steer: number; wheel: number; braking: boolean; evac: number; slide?: number; touch?: number; ex?: number; ey?: number; ez?: number; eyaw?: number }   // v: m/s có dấu; steer: rad; wheel: góc quay bánh tích lũy (rad); evac: s còn lại của lần sơ tán (0 = không sơ tán); slide: phần tốc độ còn giữ trong lần chạm vật cản hiện tại (1 = không chạm, mặc định); touch: s còn coi là đang chạm (mặc định 0); ex, ey, ez, eyaw: tư thế đích của lần sơ tán
26	export interface DrInput { gas: number; brake: number; steer: number; hand: boolean }   // gas, brake: 0..1; steer: −1..1
27	
28	const CAR = CONFIG.drive.car, P = CONFIG.drive.perf, SIM = CONFIG.drive.sim;
29	const L = CAR.wheelbase;
30	const V50 = 50 / 3.6;                                                // m/s — mốc 0–50 km/h của t50
31	const STEER_GEOM = Math.asin(L / P.turnRadius);                     // rad — góc lái lớn nhất theo hình học
32	
33	/* ===== Đường cong tăng tốc ===== */
34	let A0 = NaN, KEXP = NaN;                                            // a0 (m/s²) và số mũ k, giải lười ở lần gọi đầu
35	function drAccelK(v: number, k: number): number {
36	  if (v <= V50) return A0;
37	  if (v >= P.vMax) return 0;
38	  const u = (v - V50) / (P.vMax - V50);
39	  return A0 * V50 / v * (1 - Math.pow(u, k));
40	}
41	/* Thời gian 0 → 0,99 vMax với số mũ k (tích phân dv / a, điểm giữa) */
42	function drT100(k: number): number {
43	  const vt = 0.99 * P.vMax, N = 2000, h = (vt - V50) / N;
44	  let t = V50 / A0;
45	  for (let i = 0; i < N; i++) t += h / drAccelK(V50 + (i + 0.5) * h, k);
46	  return t;
47	}
48	function drFitAccel(): void {
49	  A0 = V50 / P.t50;
50	  let lo = 0.2, hi = 50;                                             // k nhỏ ⇒ hãm sớm ⇒ chậm hơn: drT100 giảm theo k
51	  for (let i = 0; i < 60; i++) { const m = (lo + hi) / 2; if (drT100(m) > P.t100) lo = m; else hi = m; }
52	  KEXP = (lo + hi) / 2;
53	}
54	/* m/s² khi đạp hết ga ở tốc độ v ≥ 0 */
55	export function drAccel(v: number): number {
56	  if (Number.isNaN(KEXP)) drFitAccel();
57	  return drAccelK(v, KEXP);
58	}
59	
60	/* rad — góc lái lớn nhất ở tốc độ v (dấu bỏ qua) */
61	export function drSteerMax(v: number): number {
62	  const a = Math.abs(v);
63	  if (a < 1e-6) return STEER_GEOM;
64	  const lim = Math.atan(L * P.latMax / (a * a));
65	  return lim < STEER_GEOM ? lim : STEER_GEOM;
66	}
67	
68	const drToward0 = (v: number, d: number): number => v > 0 ? (v > d ? v - d : 0) : (v < -d ? v + d : 0);
69	
70	/* Dốc dọc từ cao độ mặt đường tại trục trước / sau; giữ giá trị cũ nếu một trục không có mặt đường cùng tầng */
71	function drPitch(s: DrState, net: DrNet): void {
72	  const fx = Math.cos(s.yaw) * L / 2, fz = -Math.sin(s.yaw) * L / 2;
73	  const yf = drGround(net, s.x + fx, s.z + fz, s.y), yr = drGround(net, s.x - fx, s.z - fz, s.y);
74	  if (!Number.isNaN(yf) && !Number.isNaN(yr)) s.pitch = Math.atan2(yf - yr, L);
75	}
76	
77	/* Xe mới ở chỗ xuất phát của slot, đứng yên trên mặt đường cao nhất tại đó (mặt cầu) */
78	export function drCreate(net: DrNet, slot: number): DrState {
79	  const sp = drSpawnPose(slot);
80	  let y = -Infinity;
81	  for (const p of net.pads) {
82	    if (sp.x < p.x0 || sp.x > p.x1 || sp.z < p.z0 || sp.z > p.z1) continue;
83	    if (p.gate !== undefined && net.closed.has(p.gate)) continue;
84	    y = Math.max(y, p.y(sp.x, sp.z));
85	  }
86	  const s: DrState = { x: sp.x, y: Number.isFinite(y) ? y : CONFIG.roadY, z: sp.z, yaw: sp.yaw, pitch: 0, v: 0, steer: 0, wheel: 0, braking: false, evac: 0, slide: 1, touch: 0 };
87	  drPitch(s, net);
88	  return s;
89	}
90	
91	const MOVED: DrPose = { x: 0, y: 0, z: 0, yaw: 0 };
92	
93	/* Một bước h ≤ sim.dt */
94	function drStep1(s: DrState, inp: DrInput, net: DrNet, boxes: DrBox[], nBoxes: number, h: number): void {
95	  const g = inp.gas > 0 ? (inp.gas < 1 ? inp.gas : 1) : 0, b = inp.brake > 0 ? (inp.brake < 1 ? inp.brake : 1) : 0;
96	  let v = s.v, braking = false;
97	  /* tốc độ */
98	  if (inp.hand) { v = drToward0(v, P.handBrake * h); braking = true; }
99	  else if (b > 0 && g === 0) {
100	    if (v >= SIM.revV) { v = Math.max(0, v - b * P.brake * h); braking = true; }                       // đang tiến: phanh
101	    else v = Math.max(-P.reverseMax, v - b * (v > 0 ? P.brake : drAccel(-v)) * h);                   // gần đứng / đang lùi: lùi dần
102	  } else if (g > 0 && b === 0) {
103	    if (v < 0) { v = Math.min(0, v + g * P.brake * h); braking = true; }                             // đang lùi: phanh về 0 rồi mới tiến
104	    else v = Math.min(P.vMax, v + g * drAccel(v) * h);
105	  } else if (g > 0 && b > 0) { v = drToward0(v, b * P.brake * h); braking = true; }
106	  else v = drToward0(v, P.coast * h);
107	  /* góc lái */
108	  const lim = drSteerMax(v), want = inp.steer > 1 ? 1 : inp.steer < -1 ? -1 : inp.steer;
109	  let st = s.steer;
110	  if (want === 0) st = drToward0(st, P.steerReturn * STEER_GEOM * h);
111	  else {
112	    const tgt = want * lim, back = Math.abs(tgt) < Math.abs(st) || tgt * st < 0;
113	    const d = (back ? Math.max(P.steerRate, P.steerReturn) : P.steerRate) * STEER_GEOM * h;
114	    st = st < tgt ? Math.min(tgt, st + d) : Math.max(tgt, st - d);
115	  }
116	  if (st > lim) st = lim; else if (st < -lim) st = -lim;
117	  /* dời thân xe */
118	  const dist = v * h, f = drMove(net, s, dist, dist * Math.tan(st) / L, boxes, nBoxes, MOVED);
119	  s.x = MOVED.x; s.y = MOVED.y; s.z = MOVED.z; s.yaw = MOVED.yaw;
120	  /* va chạm: phần quãng f là cos² góc giữa hướng trượt và hướng xe, nên √f là phần tốc độ chiếu theo hướng trượt.
121	     Chỉ mất phần hướng vào vật cản khi √f xuống dưới mức nhỏ nhất đã mất trong lần chạm này (slide), không lặp lại mỗi bước
122	     khi vẫn tì vào; đang cọ thì hãm thêm perf.scrape; không bị chặn quá sim.touch giây thì coi như đã rời vật cản. */
123	  let slide = s.slide ?? 1, touch = s.touch ?? 0;
124	  if (f < 1) {
125	    if (touch > 0) v = drToward0(v, P.scrape * h);                   // đang cọ: hãm thêm
126	    const q = f > 0 ? Math.sqrt(f) : 0;
127	    if (q === 0) v = 0;                                              // đứng hẳn: đâm thẳng, hoặc tì thẳng vào mà vẫn đạp ga
128	    else if (q < slide) v *= q / slide;
129	    if (q < slide) slide = q;
130	    touch = SIM.touch;
131	  } else if (touch > 0) { touch -= h; if (touch <= 0) { touch = 0; slide = 1; } }
132	  s.slide = slide; s.touch = touch;
133	  s.v = v; s.steer = st; s.braking = braking;
134	  s.wheel += dist * f / (CAR.wheelDia / 2);
135	  drPitch(s, net);
136	}
