138	/* ===== Sơ tán khỏi nhịp quay ===== */
139	const EV = CONFIG.drive.evac, HL = CAR.length / 2, HW = CAR.width / 2;
140	const EV_POSE: DrPose = { x: 0, y: 0, z: 0, yaw: 0 }, EV_NONE: DrBox[] = [], EV_IGN = new Uint8Array(0);
141	const EV_DZ = 4, EV_DX = 10, EV_STEP = 0.25;                         // m — tìm chỗ đậu: lệch ngang tối đa, lùi xa barie tối đa, bước tìm
142	
143	/* Thân xe còn chạm ô mang cổng đang đóng: một trong 9 điểm mẫu nằm trong ô đó (cùng tầng) mà không có mặt đường mở nào cùng tầng */
144	function drOnClosedGate(net: DrNet, s: DrState): boolean {
145	  if (net.closed.size === 0) return false;
146	  const c = Math.cos(s.yaw), sn = Math.sin(s.yaw), pads = net.pads, step = CONFIG.drive.stepMax;
147	  for (let i = -1; i <= 1; i++) for (let j = -1; j <= 1; j++) {
148	    const px = s.x + i * HL * c + j * HW * sn, pz = s.z - i * HL * sn + j * HW * c;
149	    if (!Number.isNaN(drGround(net, px, pz, s.y))) continue;
150	    for (let k = 0; k < pads.length; k++) {
151	      const p = pads[k];
152	      if (p.gate === undefined || !net.closed.has(p.gate) || px < p.x0 || px > p.x1 || pz < p.z0 || pz > p.z1) continue;
153	      if (Math.abs(p.y(px, pz) - s.y) <= step) return true;
154	    }
155	  }
156	  return false;
157	}
158	/* Chỗ đậu sau sơ tán, ghi vào s.ex / ey / ez / eyaw: ngoài barie gần nhất (đuôi xe cách barie evac.gap), hướng dọc cầu gần hướng xe nhất;
159	   thân xe phải có mặt đường đủ 9 điểm và không chồng vật cản tĩnh (hộp xe tự động không tính: đã chồng thì drMove bỏ qua).
160	   Lệch ngang dần tới EV_DZ, lùi xa dần tới EV_DX; bên gần không được thì thử bên kia. Không ở đâu được thì false */
161	function drEvacTarget(net: DrNet, s: DrState): boolean {
162	  const yaw = Math.cos(s.yaw) >= 0 ? 0 : Math.PI, first = s.x >= 0 ? 1 : -1;
163	  for (let side = first, t = 0; t < 2; t++, side = -side) {
164	    for (let dx = 0; dx <= EV_DX; dx += 1) for (let k = 0; k <= 2 * EV_DZ / EV_STEP; k++) {
165	      const x = side * (SH.barrierX + HL + EV.gap + dx), z = s.z + (k % 2 ? 1 : -1) * Math.ceil(k / 2) * EV_STEP;
166	      const y = drGround(net, x, z, s.y);
167	      if (Number.isNaN(y)) continue;
168	      EV_POSE.x = x; EV_POSE.y = y; EV_POSE.z = z; EV_POSE.yaw = yaw;
169	      if (!drFits(net, EV_POSE, EV_NONE, 0, EV_IGN)) continue;
170	      s.ex = x; s.ey = y; s.ez = z; s.eyaw = yaw;
171	      return true;
172	    }
173	  }
174	  return false;
175	}
176	/* Một khung sơ tán. Chưa sơ tán: bắt đầu nếu thân xe chạm ô có cổng đóng (budget: s còn lại tới lúc nhịp bắt đầu xoay; bỏ trống = không hạn, ≤ 0 = hết hạn ⇒ trượt trong evac.minTime).
177	   Đang sơ tán: bỏ qua đầu vào, xe đứng (v = 0), nội suy đều tới chỗ đậu, hết s.evac thì tới đúng chỗ. Trả true khi khung này dành cho sơ tán */
178	export function drEvacStep(s: DrState, net: DrNet, dt: number, budget?: number): boolean {
179	  if (!(s.evac > 0)) {
180	    if (!drOnClosedGate(net, s)) return false;
181	    if (!drEvacTarget(net, s)) {                                     // không có chỗ đậu (dữ liệu sai): về chỗ xuất phát
182	      const c = drCreate(net, -1);
183	      s.x = c.x; s.y = c.y; s.z = c.z; s.yaw = c.yaw; s.pitch = c.pitch;
184	      s.v = 0; s.steer = 0; s.braking = false; s.slide = 1; s.touch = 0;
185	      return true;
186	    }
187	    const d = Math.hypot(s.ex - s.x, s.ez - s.z), want = Math.max(d / EV.speed, EV.minTime);
188	    s.evac = Math.max(1e-3, budget === undefined ? want : budget > 0 ? Math.min(want, budget * EV.share) : EV.minTime);   // 0: nhịp đã / đang xoay (tab ẩn rồi quay lại), không trượt chậm qua nhịp
189	  }
190	  s.v = 0; s.steer = 0; s.braking = false; s.slide = 1; s.touch = 0;
191	  if (!(dt > 0)) return true;
192	  const f = dt >= s.evac ? 1 : dt / s.evac, ox = s.x, oz = s.z;
193	  let dy = (s.eyaw - s.yaw) % (2 * Math.PI);
194	  if (dy > Math.PI) dy -= 2 * Math.PI; else if (dy < -Math.PI) dy += 2 * Math.PI;
195	  s.x += (s.ex - s.x) * f; s.z += (s.ez - s.z) * f; s.yaw += dy * f;
196	  const g = drGround(net, s.x, s.z, s.y);
197	  s.y = Number.isNaN(g) ? s.y + (s.ey - s.y) * f : g;               // trên ô đã đóng: nội suy cao độ
198	  s.evac -= dt;
199	  if (s.evac <= 0) { s.evac = 0; s.x = s.ex; s.y = s.ey; s.z = s.ez; s.yaw = s.eyaw; }
200	  s.wheel += ((s.x - ox) * Math.cos(s.yaw) - (s.z - oz) * Math.sin(s.yaw)) / (CAR.wheelDia / 2);   // bánh lăn theo quãng dọc thân xe
201	  drPitch(s, net);
202	  return true;
203	}
204	
205	/* Bước mô phỏng cho khung dài dt (s). Đang / cần sơ tán khỏi nhịp quay thì khung dành cho sơ tán, đầu vào bỏ qua */
206	export function drStep(s: DrState, inp: DrInput, net: DrNet, boxes: DrBox[], nBoxes: number, dt: number): void {
207	  if (drEvacStep(s, net, dt)) return;
208	  let rem = dt;
209	  for (let k = 0; k < SIM.steps && rem > 1e-6; k++) {
210	    const h = rem < SIM.dt ? rem : SIM.dt;
211	    drStep1(s, inp, net, boxes, nBoxes, h);
212	    rem -= h;
213	  }
214	}
