1	/* ============================ Lái xe: camera sau xe ============================
2	   Camera sau xe `cam.dist`, cao `cam.height` trên mặt đường dưới xe, nhìn vào điểm trước tâm xe `lookAhead`, cao `look` (spec §3 mục 4).
3	   - Hướng camera bám hướng THÂN xe (không theo vận tốc) với trễ `lag`: lùi xe thì camera vẫn ở sau đuôi, không quay ra trước.
4	     Vị trí bám thẳng tâm xe (không trễ), để ở 100 km/h camera không tụt xa.
5	   - Người chơi kéo chuột thêm lệch yaw / pitch (DrCam); thôi kéo `returnAfter` giây thì lệch về 0 theo `returnRate`.
6	   - Xe trong ô 'tunnel' (cả đoạn hở) thì khoảng lùi `tunnelDist`, độ cao `tunnelHeight`; độ cao kẹp dưới trần ống (hrRoadY + hanTunnel.clear − roof)
7	     khi xe hoặc camera ở trong ô hầm (drSegClear không biết trần hầm nên kẹp ở đây).
8	   - Đoạn từ điểm nhìn trên xe tới chỗ camera muốn đứng vướng vật cản (drSegClear < 1): kéo gần (lùi thêm `gap`, không dưới `minDist`)
9	     và hạ về `tunnelHeight`. Khoảng lùi co lại ngay, nở ra theo `lag` (không giật khi vừa thoát góc tường); độ cao đổi mượt theo `lag`.
10	   - Không thấp hơn mặt đường tại chỗ camera + `floor` (không có mặt đường cùng tầng thì so với mặt đường dưới xe).
11	   Gầm cầu (đường ven sông chui dưới dốc Trần Thị Lý) chưa kiểm: vật cản không có mặt cầu. Không cấp phát (D-018). */
12	import type * as THREE from 'three';
13	import { CONFIG } from '../../config';
14	import { HR, hrRoadY } from '../../bridges/han-tunnel/profile';
15	import { drGround, type DrNet } from './net';
16	import { drSegClear } from './collide';
17	import type { DrState } from './motion';
18	
19	export interface DrCam { yaw: number; pitch: number; idle: number }   // yaw, pitch: lệch do người chơi kéo (rad); idle: giây từ lần kéo cuối
20	
21	const DR_TUNNEL_DY = 2;                       // m — ô hầm chứa (x, z) được tính khi mặt đường ô lệch cao độ tham chiếu không quá chừng này (đường ven sông chạy trên hầm cách ≥ 10 m)
22	const cs = { ok: false, head: 0, dist: 0, height: 0 };   // hướng đã trễ, khoảng lùi và độ cao đang dùng
23	const TAU = Math.PI * 2;
24	const wrap = (a: number): number => a - TAU * Math.round(a / TAU);
25	
26	/* (x, z) nằm trong ô 'tunnel' gần cao độ y không (duyệt tuyến tính, không cấp phát) */
27	function drInTunnel(net: DrNet, x: number, z: number, y: number): boolean {
28	  const pads = net.pads;
29	  for (let i = 0; i < pads.length; i++) {
30	    const p = pads[i];
31	    if (p.kind !== 'tunnel' || x < p.x0 || x > p.x1 || z < p.z0 || z > p.z1) continue;
32	    if (Math.abs(p.y(x, z) - y) <= DR_TUNNEL_DY) return true;
33	  }
34	  return false;
35	}
36	
37	export function drCamPlace(camera: THREE.PerspectiveCamera, s: Pick<DrState, 'x' | 'y' | 'z' | 'yaw'>, c: DrCam, net: DrNet, dt: number, snap?: boolean): void {
38	  const K = CONFIG.drive.cam;
39	  /* 1) lệch do kéo tự về sau returnAfter giây */
40	  if (!snap && dt > 0) {
41	    c.idle += dt;
42	    if (c.idle > K.returnAfter) { const k = Math.exp(-K.returnRate * dt); c.yaw *= k; c.pitch *= k; }
43	  }
44	  /* 2) hướng bám thân xe, có trễ */
45	  const tun = drInTunnel(net, s.x, s.z, s.y);
46	  let dist = tun ? K.tunnelDist : K.dist, height = tun ? K.tunnelHeight : K.height;
47	  const first = snap || !cs.ok || !(dt > 0), k = first ? 1 : 1 - Math.exp(-K.lag * dt);
48	  if (first) { cs.head = s.yaw; cs.ok = true; } else cs.head = wrap(cs.head + wrap(s.yaw - cs.head) * k);
49	  /* 3) chỗ camera muốn đứng, cắt theo vật cản từ điểm nhìn trên xe */
50	  const yaw = cs.head + c.yaw, cp = Math.cos(c.pitch), sp = Math.sin(c.pitch), fx = Math.cos(yaw), fz = -Math.sin(yaw);
51	  const ay = s.y + K.look;
52	  const t = drSegClear(net, s.x, ay, s.z, s.x - fx * dist * cp, s.y + height + dist * sp, s.z - fz * dist * cp);
53	  if (t < 1) { const d = dist * t - K.gap; dist = d > K.minDist ? d : K.minDist; if (height > K.tunnelHeight) height = K.tunnelHeight; }
54	  if (first || dist < cs.dist) cs.dist = dist; else cs.dist += (dist - cs.dist) * k;
55	  if (first) cs.height = height; else cs.height += (height - cs.height) * k;
56	  const cx = s.x - fx * cs.dist * cp, cz = s.z - fz * cs.dist * cp;
57	  let cy = s.y + cs.height + cs.dist * sp;
58	  /* 4) dưới trần ống hầm (xe hoặc camera trong ô hầm) */
59	  if (tun || drInTunnel(net, cx, cz, s.y)) { const roof = hrRoadY(cx) + HR.clear - K.roof; if (cy > roof) cy = roof; }
60	  /* 5) trên mặt đường tại chỗ camera */
61	  const g = drGround(net, cx, cz, s.y), floor = (g === g ? g : s.y) + K.floor;
62	  if (cy < floor) cy = floor;
63	  camera.position.set(cx, cy, cz);
64	  const hx = Math.cos(s.yaw), hz = -Math.sin(s.yaw);
65	  camera.lookAt(s.x + hx * K.lookAhead, ay, s.z + hz * K.lookAhead);
66	}
67	
68	/* Kéo chuột: sang phải quay camera sang phải (yaw giảm), kéo xuống nâng camera nhìn xuống (pitch tăng); đặt lại đồng hồ tự về */
69	export function drCamDrag(c: DrCam, dxPx: number, dyPx: number): void {
70	  const K = CONFIG.drive.cam;
71	  c.yaw = wrap(c.yaw - dxPx * K.mouse);   // trong ±π: tự về theo đường ngắn nhất
72	  c.pitch += dyPx * K.mouse;
73	  if (c.pitch < K.pitchMin) c.pitch = K.pitchMin; else if (c.pitch > K.pitchMax) c.pitch = K.pitchMax;
74	  c.idle = 0;
75	}
