1	/* ============================ Lái xe: tiếng mô tơ điện và còi ============================
2	   Tổng hợp bằng Web Audio, không tệp âm thanh. Dùng chung AudioContext của trang (audio/index.ts):
3	   - Âm thanh chung đã bật (nút nhạc, hoặc cờ đã lưu): nối vào nút hiệu ứng (sfxPort → master), tắt tiếng / âm lượng chung chặn / chỉnh luôn tiếng xe.
4	   - Chưa bật: im lặng cho tới khi người xem bấm nút 🔊 (#drSoundBtn trong #drHud; nút nhạc ẩn trong chế độ khám phá): lần bấm đó tạo / resume ngữ cảnh
5	     qua audio.extPort (cổng riêng, không qua master, không phát nhạc nền). Không tự tạo AudioContext ngoài thao tác của người xem (chính sách autoplay).
6	   - Nút 🔊 / 🔇 bật / tắt riêng tiếng xe; lựa chọn giữ trong trang (drSoundWanted: đã bấm thì theo lựa chọn, chưa bấm thì theo âm thanh chung).
7	   - Mô tơ: hai dao động (tam giác + sin ở quãng tám trên) qua lọc thông thấp, tần số và âm lượng theo |v|. Còi: hai nốt vuông cùng bật / tắt.
8	   - update chỉ ghi tham số tối đa mỗi CONFIG.drive.sound.updateMs (mỗi lần là một sự kiện tự động hoá, D-018). stop() dừng và ngắt mọi nút. */
9	import { CONFIG } from '../../config';
10	import { audio } from '../../audio';
11	
12	interface DrSnd { ctx: AudioContext; o1: OscillatorNode; o2: OscillatorNode; lp: BiquadFilterNode; g: GainNode; hg: GainNode; h: OscillatorNode[]; ext: boolean }
13	let snd: DrSnd | null = null;
14	let want = false, hornOn = false, lastAt = -1e9;
15	let pick: boolean | null = null;                 // lựa chọn của người xem bằng nút 🔊 (giữ trong trang); null = chưa bấm
16	let btn: HTMLElement | null = null, shown: boolean | null = null;
17	
18	/* Có tiếng xe không: đã bấm nút thì theo lựa chọn; chưa bấm thì theo âm thanh chung (giữ hành vi cũ: ai đã bật nhạc thì có tiếng xe) */
19	export function drSoundWanted(p: boolean | null, globalOn: boolean): boolean { return p === null ? globalOn : p; }
20	/* Đường ra: âm thanh chung đang bật ⇒ nút hiệu ứng chung (qua master); không ⇒ cổng riêng nếu người xem đã bật bằng nút; còn lại không phát */
21	export function drSoundRoute(p: boolean | null, globalOn: boolean): 'sfx' | 'ext' | null {
22	  if (!drSoundWanted(p, globalOn)) return null;
23	  return globalOn ? 'sfx' : p === true ? 'ext' : null;
24	}
25	const globalOn = (): boolean => { const p = audio.sfxPort(); return !!p && p.on; };
26	
27	/* Dựng chuỗi nút nếu có đường ra; trả có dựng được không */
28	function drSndBuild(): boolean {
29	  const route = drSoundRoute(pick, globalOn());
30	  const port = route === 'sfx' ? audio.sfxPort() : route === 'ext' ? audio.extPort() : null;
31	  if (!port) return false;
32	  const S = CONFIG.drive.sound, { ctx, out } = port;
33	  const lp = ctx.createBiquadFilter(); lp.type = 'lowpass'; lp.frequency.value = S.lowpass;
34	  const g = ctx.createGain(); g.gain.value = 0;
35	  const o1 = ctx.createOscillator(); o1.type = 'triangle'; o1.frequency.value = S.base;
36	  const o2 = ctx.createOscillator(); o2.type = 'sine'; o2.frequency.value = S.base * 2;
37	  const mix = ctx.createGain(); mix.gain.value = 0.5;
38	  o1.connect(lp); o2.connect(mix).connect(lp); lp.connect(g).connect(out);
39	  const hg = ctx.createGain(); hg.gain.value = hornOn ? S.hornGain : 0;
40	  const h = S.hornHz.map((f) => { const o = ctx.createOscillator(); o.type = 'square'; o.frequency.value = f; o.connect(hg); o.start(); return o; });
41	  hg.connect(out);
42	  o1.start(); o2.start();
43	  snd = { ctx, o1, o2, lp, g, hg, h, ext: route === 'ext' };
44	  return true;
45	}
46	/* Dừng và ngắt chuỗi nút (giữ want / pick); thả cổng riêng nếu đang dùng */
47	function drSndTear(): void {
48	  if (!snd) return;
49	  for (const o of [snd.o1, snd.o2, ...snd.h]) { try { o.stop(); } catch { /* đã dừng */ } o.disconnect(); }
50	  snd.lp.disconnect(); snd.g.disconnect(); snd.hg.disconnect();
51	  if (snd.ext) audio.extPort(false);
52	  snd = null;
53	}
54	/* Nút 🔊 / 🔇: biểu tượng + aria-pressed theo trạng thái (chỉ ghi DOM khi đổi) */
55	function drSndSync(force = false): void {
56	  if (!btn) return;
57	  const on = want && drSoundWanted(pick, globalOn());
58	  if (!force && on === shown) return;
59	  shown = on;
60	  btn.textContent = on ? '🔊' : '🔇';
61	  btn.setAttribute('aria-pressed', String(on));
62	}
63	
64	export const drSound = {
65	  /* Gắn nút bật / tắt (#drSoundBtn); bấm = toggle (trong thao tác của người xem nên tạo / resume được ngữ cảnh) */
66	  bind(el: HTMLElement | null): void {
67	    btn = el;
68	    if (el) el.addEventListener('click', () => { drSound.toggle(); });
69	    drSndSync(true);
70	  },
71	  /* Vào chế độ lái: bật mô tơ nếu có đường ra (nếu chưa, update thử lại khi âm thanh chung bật sau) */
72	  start(): void { want = true; lastAt = -1e9; if (!snd) drSndBuild(); drSndSync(true); },
73	  /* Bật / tắt tiếng xe theo lựa chọn của người xem; trả trạng thái mới */
74	  toggle(): boolean {
75	    pick = !drSoundWanted(pick, globalOn());
76	    if (pick) { lastAt = -1e9; if (!snd && want) drSndBuild(); } else drSndTear();
77	    drSndSync();
78	    return pick;
79	  },
80	  /* Đang có tiếng xe (theo lựa chọn / âm thanh chung) không */
81	  get on(): boolean { return want && drSoundWanted(pick, globalOn()); },
82	  /* Mỗi khung với tốc độ v (m/s, có dấu): ghi tham số tối đa mỗi updateMs */
83	  update(v: number): void {
84	    if (!want) return;
85	    const now = performance.now();
86	    if (now - lastAt < CONFIG.drive.sound.updateMs) return;
87	    lastAt = now;
88	    drSndSync();                                   // âm thanh chung có thể vừa bật (chạm đầu tiên khi đã lưu cờ nhạc)
89	    if (!drSoundWanted(pick, globalOn())) return;
90	    if (!snd && !drSndBuild()) return;
91	    const S = CONFIG.drive.sound, a = Math.abs(v), k = Math.min(1, a / CONFIG.drive.perf.vMax), t = snd!.ctx.currentTime;
92	    snd!.o1.frequency.setTargetAtTime(S.base + S.perMs * a, t, S.smooth);
93	    snd!.o2.frequency.setTargetAtTime((S.base + S.perMs * a) * 2, t, S.smooth);
94	    snd!.g.gain.setTargetAtTime(S.gainIdle + (S.gainMax - S.gainIdle) * k, t, S.smooth);
95	  },
96	  /* Còi (giữ phím H): đổi trạng thái mới ghi tham số */
97	  horn(on: boolean): void {
98	    if (on === hornOn) return;
99	    hornOn = on;
100	    if (snd) snd.hg.gain.setTargetAtTime(on ? CONFIG.drive.sound.hornGain : 0, snd.ctx.currentTime, 0.02);
101	  },
102	  /* Rời chế độ: dừng các dao động và ngắt nút (lựa chọn của nút giữ lại cho lần lái sau trong trang) */
103	  stop(): void {
104	    want = false; hornOn = false;
105	    drSndTear();
106	    drSndSync();
107	  }
108	};
109

/* ===== Dù lượn nhiều người: định dạng tin khách ⇄ máy chủ (JSON) ===== */
import { multiParams } from './params';

export type ClientMsg =
  | { t: 'join'; name: string; kind?: 'walk' | 'drive'; ch?: number }   // kind: 'walk' = xin chỗ đi dạo, 'drive' = chỗ lái xe; không có = chỗ bay (khách cũ). ch: nhân vật đi dạo (0 nam, 1 nữ), chỉ kèm kind 'walk'; khách cũ không gửi = nam
  | { t: 'pos'; x: number; y: number; z: number; yaw: number; bank: number; ts?: number }   // ts: giờ gửi theo đồng hồ của khách (ms); máy chủ cũ bỏ qua
  | { t: 'pos'; x: number; y: number; z: number; yaw: number; pose: number; ts?: number }   // người đi dạo: pose (0 đứng, 1 đi, 2 chạy, 3 rơi (bản cũ: nhảy), 4 chụp ảnh), không có bank
  | { t: 'pos'; x: number; y: number; z: number; yaw: number; v: number; st: number; ts?: number }   // người lái: v tốc độ có dấu (m/s), st góc lái (rad); không có bank / pose
  | { t: 'hb' }
  | { t: 'leave' };

export interface Flyer { slot: number; name: string; ch?: number }   // ch: nhân vật của người đi dạo (chỉ có trong walkers; máy chủ cũ không gửi = nam)

/* Nhân vật đi dạo hợp lệ: 1 = nữ, mọi giá trị khác (không có, khách / máy chủ cũ, số lạ) = 0 nam */
export function exCharNorm(v: unknown): number { return v === 1 ? 1 : 0; }

export type Kind = 'fly' | 'walk' | 'drive';

// f: mỗi phần tử [slot, x, y, z, yaw, bank, giờ gửi (ms)]; chỉ gồm slot có vị trí mới. Giờ gửi = ts của khách, khách cũ không gửi ts thì là giờ máy chủ nhận;
// mỗi slot một trục giờ riêng, khách nhận tự quy đổi. Máy chủ cũ (trước bản sửa giật) gửi 6 phần tử và phát lại vị trí cũ của mọi slot: khách mới nhận được cả hai dạng.
// Đi dạo: lobby thêm walkers (flyers chỉ có người bay; mỗi người đi dạo kèm ch = nhân vật họ chọn, nên máy vào sau cũng biết ngay từ lobby đầu), pos thêm w (mỗi phần tử [slot, x, y, z, yaw, pose, giờ gửi]; f luôn có, có thể rỗng); khách cũ bỏ qua trường lạ
// Lái xe: lobby thêm drivers, pos thêm d (mỗi phần tử [slot, x, y, z, yaw, v, st, giờ gửi]); máy chủ cũ không gửi drivers, khách mới thấy vậy thì lái một mình
export type ServerMsg =
  | { t: 'lobby'; flyers: Flyer[]; walkers?: Flyer[]; drivers?: Flyer[] }
  | { t: 'joined'; slot: number; kind?: 'walk' | 'drive' }
  | { t: 'rejected'; why: 'full' | 'name'; kind?: 'walk' | 'drive' }
  | { t: 'pos'; f: number[][]; w?: number[][]; d?: number[][] }   // d: [slot, x, y, z, yaw, v, st, giờ gửi]
