21	const M = CONFIG.drive.model, CAR = CONFIG.drive.car;
22	const WHEELS = ['wheel_fl', 'wheel_fr', 'wheel_rl', 'wheel_rr'];   // hai bánh đầu là bánh trước
23	const CAP = (multiParams.slots + 1) * 4;                           // chỗ bánh: 6 xe × 4
