27	/* ===== Vật liệu đèn: vá phát sáng theo uNight, hệ số `night`; uBrake > phát sáng nền thì thay bằng uBrake ===== */
28	function drLampPatch(m: THREE.MeshStandardMaterial, key: string, night: number, brake: number): void {
29	  const ub = { value: brake };
30	  m.onBeforeCompile = (s) => {
31	    s.uniforms.uNight = shared.uNight;
32	    s.uniforms.uBrake = ub;
33	    s.fragmentShader = 'uniform float uNight;\nuniform float uBrake;\n' + s.fragmentShader.replace('#include <emissivemap_fragment>',
34	      `#include <emissivemap_fragment>\ntotalEmissiveRadiance *= max( clamp( uNight, 0.0, 1.0 ) * ${night.toFixed(3)}, uBrake );`);
35	  };
36	  m.customProgramCacheKey = () => key;
37	  m.userData.lampBrake = brake;
38	}
