40	export interface DrSource {
41	  scene: THREE.Object3D;                       // cảnh gốc (không thêm vào cảnh; chỉ để sao chép)
42	  body: THREE.Object3D;                        // nút body
43	  paint: THREE.MeshStandardMaterial;           // vật liệu sơn gốc (mỗi xe nhân bản)
44	  tail: THREE.Material; tailBrake: THREE.Material;
45	  wheels: { pos: THREE.Vector3; quat: THREE.Quaternion; sign: number }[];   // vị trí, xoay nghỉ, dấu quay quanh Z cục bộ (4 bánh theo WHEELS)
46	  wheelMeshes: THREE.Mesh[];                   // các lưới của wheel_fl (mỗi vật liệu một lưới)
