49	/* Chuẩn hóa cảnh đã nạp thành nguồn dùng chung. Thiếu nút / vật liệu thì ném lỗi (drCarLoad bắt, trả null) */
50	export function drCarSource(scene: THREE.Object3D): DrSource {
51	  scene.updateMatrixWorld(true);
52	  const body = scene.getObjectByName('body');
53	  if (!body) throw new Error('thiếu nút body');
54	  let paint: THREE.MeshStandardMaterial | null = null, head: THREE.MeshStandardMaterial | null = null, tail: THREE.MeshStandardMaterial | null = null;
55	  scene.traverse((o) => {
56	    o.layers.set(1);
57	    const me = o as THREE.Mesh;
58	    if (!me.isMesh) return;
59	    me.castShadow = false; me.receiveShadow = false;
60	    const mat = me.material as THREE.MeshStandardMaterial;
61	    if (mat.name === 'paint') paint = mat;
62	    else if (mat.name === 'lamp_head') head = mat;
63	    else if (mat.name === 'lamp_tail') tail = mat;
64	    else if (mat.name === 'Material.002') mat.roughness = M.glassRough;   // kính: nguồn nhám 0 ⇒ điểm chói trăng loang xanh (cả bản sao thân dùng chung vật liệu này)
65	  });
66	  if (!paint || !head || !tail) throw new Error('thiếu vật liệu paint / lamp_head / lamp_tail');
67	  const h = head as THREE.MeshStandardMaterial, t = tail as THREE.MeshStandardMaterial;
68	  drLampPatch(h, 'drLampHead', M.headNight, 0);
69	  t.emissive.set(M.tailTint); t.emissiveMap = t.map; t.emissiveIntensity = 1;   // không emissive map: lấy chính ảnh màu cơ bản, nhuộm đỏ (ảnh dán nhạt × trắng = hồng)
70	  drLampPatch(t, 'drLampTail', M.tailNight, 0);
71	  const tb = t.clone(); drLampPatch(tb, 'drLampTail', M.tailNight, M.tailBrake);   // cùng khóa program: chỉ khác uniform
72	  const wheels: DrSource['wheels'] = [], z = new THREE.Vector3();
73	  for (const n of WHEELS) {
74	    const w = scene.getObjectByName(n);
75	    if (!w) throw new Error(`thiếu nút ${n}`);
76	    z.set(0, 0, 1).applyQuaternion(w.quaternion);
77	    wheels.push({ pos: w.position.clone(), quat: w.quaternion.clone(), sign: z.z > 0 ? -1 : 1 });   // bánh tiến: quanh +Z thế giới góc âm
78	  }
79	  const wheelMeshes: THREE.Mesh[] = [];
80	  scene.getObjectByName(WHEELS[0]).traverse((o) => { if ((o as THREE.Mesh).isMesh) wheelMeshes.push(o as THREE.Mesh); });
81	  if (!wheelMeshes.length) throw new Error('bánh không có lưới');
82	  return { scene, body, paint: paint as THREE.MeshStandardMaterial, tail: t, tailBrake: tb, wheels, wheelMeshes };
83	}
