88	async function drCarWarm(o: THREE.Object3D): Promise<void> {
89	  if (!warm) return;
90	  let timer = 0;
91	  try { await Promise.race([warm(o), new Promise<void>((r) => { timer = setTimeout(r, M.warmMs) as unknown as number; })]); }
92	  catch { /* biên dịch trước lỗi: lần vẽ đầu tự biên dịch */ }
93	  finally { clearTimeout(timer); }
94	}
