97	   hình tạm (driveTemp) và tấm bóng (driveShadow). Nhóm tạm gồm cảnh nguồn + một InstancedMesh 1 chỗ mỗi lưới bánh + một hình tạm + một tấm bóng;
98	   gỡ cảnh nguồn ra (về không cha) và bỏ nhóm sau khi làm nóng. Đèn hậu phanh cùng program với đèn hậu (cùng khóa) nên không cần */
99	async function drCarWarmAll(src: DrSource): Promise<void> {
100	  if (!warm) return;
101	  const g = new THREE.Group(), ims: THREE.InstancedMesh[] = [];
102	  for (const m of src.wheelMeshes) { const im = new THREE.InstancedMesh(m.geometry, m.material, 1); im.layers.set(1); ims.push(im); g.add(im); }
103	  const tg = drTempGeometry('#808080');
104	  g.add(new THREE.Mesh(tg, drTempMaterial()));
105	  drShadowShared(); g.add(new THREE.Mesh(shadowGeo!, shadowMat!));
106	  g.add(src.scene);
107	  try { await drCarWarm(g); }
108	  finally { g.remove(src.scene); for (const im of ims) im.dispose(); tg.dispose(); }
109	}
