22	    }
23	    for (const [s, c] of cars) if (!want.has(s)) { c.dispose(); cars.delete(s); }
24	  },
25	  place(slot: number, p: DrPlace): void { cars.get(slot)?.place(p); },
26	  /* Số xe đang có (0 = group không có gì để vẽ, người gọi gỡ khỏi cảnh) */
